"""Builds TEST_RESULTS.md from what the campaign actually produced (JUnit XML, campaign.tsv, JSON result files). Nothing is typed by hand."""

import json
import xml.etree.ElementTree as ET
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
RES = ROOT / "ci" / "results"
out = [
    "# SovereignStream — Test results",
    "",
    "Generated by `ci/make_results.py` from the files in `ci/results/` and the result JSON files. Local run on one machine ([PERFORMANCE.md](PERFORMANCE.md) lists it).",
    "",
]
stages = []
tsv = RES / "campaign.tsv"
if tsv.exists():
    for line in tsv.read_text().splitlines():
        n, rc, start, secs = line.split("\t")
        stages.append((n, int(rc), start, int(secs)))
out += ["## Stages", "", "| Stage | Result | Started | Duration |", "|---|---|---|---|"]
for n, rc, start, secs in stages:
    out.append(f"| {n} | {'PASS' if rc == 0 else f'FAIL (exit {rc})'} | {start} | {secs // 60} min {secs % 60} s |")
out += ["", "## Test counts (from JUnit XML)", "", "| File | Tests | Failures | Errors | Skipped | Time |", "|---|---|---|---|---|---|"]
tot = [0, 0, 0, 0]
for f in sorted(RES.glob("*.xml")):
    try:
        root = ET.parse(f).getroot()
    except ET.ParseError:
        continue
    suites = [root] if root.tag == "testsuite" else list(root.iter("testsuite"))
    t = sum(int(s.get("tests", 0)) for s in suites)
    fl = sum(int(s.get("failures", 0)) for s in suites)
    er = sum(int(s.get("errors", 0)) for s in suites)
    sk = sum(int(s.get("skipped", 0)) for s in suites)
    tm = sum(float(s.get("time", 0)) for s in suites)
    out.append(f"| {f.name} | {t} | {fl} | {er} | {sk} | {tm:.0f} s |")
    for i, v in enumerate((t, fl, er, sk)):
        tot[i] += v
out.append(f"| **total** | **{tot[0]}** | **{tot[1]}** | **{tot[2]}** | **{tot[3]}** | |")
extra = sorted(RES.glob("kafka-infrastructure.txt"))
if extra:
    out += ["", "## Kafka infrastructure tests A–E (shell)", "", "```"] + [l for l in extra[0].read_text().splitlines()] + ["```"]
for title, path in (
    ("DR chain A→B→C (test_dr.py)", "policy/tests/dr-results.json"),
    ("Split brain, degraded RPO and failback (test_dr_failback.py)", "policy/tests/dr-failback-results.json"),
    ("Stale tertiary replica (test_dr_stale_c.py)", "policy/tests/dr-stale-c-results.json"),
):
    p = ROOT / path
    if p.exists():
        out += ["", f"## Measured values: {title}", "", "```json", json.dumps(json.loads(p.read_text()), indent=1, sort_keys=True), "```"]
SCENARIOS = [
    (
        1,
        "Normal operation",
        "EU-restricted topic: persists locally, replicates A→B (C prohibited); GLOBAL topic A→B and A→C; matching event ids and per-partition order",
        ["test_scenario_1_"],
    ),
    (
        2,
        "Residency rejection",
        "flow into the prohibited region refused at the policy engine, batch refused by the receiver, nothing written, audit entries, chain intact",
        ["test_scenario_2_", "test_12_unauthorized_topic_is_never_replicated", "test_a_prohibited_route_is_never_selected"],
    ),
    (
        3,
        "Network degradation",
        "latency + bandwidth on path A → route switches to path B; replication continues; checkpoints and order intact; switch audited",
        ["test_path_b_is_selected_when_a_degrades"],
    ),
    (
        4,
        "All paths unavailable",
        "local publishing continues; backlog accumulates; backpressure at the hard threshold; catch-up after restore",
        ["test_all_paths_down_pauses_replication"],
    ),
    (
        5,
        "Broker failure",
        "broker stopped: Kafka elects a leader, gateway keeps accepting writes; second broker: acks=all writes refused",
        ["test_01_dr01_primary_broker_dies", "test_02_dr02_second_broker_dies"],
    ),
    (
        6,
        "Primary regional failure",
        "A killed: B promoted, epoch incremented, A fenced, clients and consumers reconnect",
        ["test_05_dr03_dr08_region_a_fails", "test_08_dr06_dr07_restored_old_regions_stay_fenced"],
    ),
    (
        7,
        "Secondary regional failure",
        "B's new events replicate to C; B killed with A already lost: C promoted through the witness quorum; recovery position measured",
        ["test_06_dr04_events_written_in_b_replicate_to_c", "test_07_dr05_dr11_dr13_region_b_fails"],
    ),
    (
        8,
        "Stale tertiary replica",
        "C made stale, B fails: automatic promotion refused; degraded recovery refused",
        ["test_scenario_8_stale_c_blocks_automatic_promotion"],
    ),
    (
        9,
        "Split brain",
        "old primary alive, cut off from the coordinator, reachable by a client: its lease expires, writes rejected, one authority",
        ["test_01_split_brain_false_positive"],
    ),
    (
        10,
        "Coordinator failure",
        "quorum removed: no promotion, active region stops writing; witnesses lost too: fail closed",
        ["test_03_dr10_coordinator_quorum_lost", "test_09_dr12_witnesses_lost_too"],
    ),
    (
        11,
        "Failback",
        "restored A stays fenced; divergent data quarantined and reconciled; approved failback; single active leader",
        ["test_02_failback_a_is_validated", "test_03_approved_failback_fences_b", "test_04_old_active_and_the_third_region_are_reprotected"],
    ),
]
cases: dict[str, str] = {}
for f in sorted(RES.glob("*.xml")):
    try:
        root = ET.parse(f).getroot()
    except ET.ParseError:
        continue
    for tc in root.iter("testcase"):
        bad = tc.find("failure") is not None or tc.find("error") is not None
        skipped = tc.find("skipped") is not None
        cases[tc.get("name", "")] = "FAIL" if bad else ("skipped" if skipped else "pass")
out += [
    "",
    "## The eleven end-to-end scenarios (details and honest gaps in [SCENARIOS.md](SCENARIOS.md))",
    "",
    "| # | Scenario | What is asserted | Tests | Result |",
    "|---|---|---|---|---|",
]
for n, title, what, keys in SCENARIOS:
    res = []
    for k in keys:
        m = [v for name, v in cases.items() if k in name]
        res.append(m[-1] if m else "not run")
    verdict = "PASS" if all(r == "pass" for r in res) else ("FAIL" if "FAIL" in res else "incomplete: " + ", ".join(res))
    out.append(f"| {n} | {title} | {what} | {len(keys)} | {verdict} |")
(ROOT / "TEST_RESULTS.md").write_text("\n".join(out) + "\n")
print("wrote TEST_RESULTS.md")
